insert into ops.quality_grades (sample_ref, faculty, rule, severity, passed, note, exact_text, owner_agent, judge_model, graded_at)
select x.sample_ref, x.faculty, x.rule, x.severity, false, x.note, x.exact_text, x.owner_agent, 'claude-haiku-4-5-20251001', x.graded_at::timestamptz
from json_to_recordset($1::json) as x(sample_ref text, faculty text, rule text, severity text, note text, exact_text text, owner_agent text, graded_at text);

