parameters.query:
update ops.proposals p set verdict = case when g.verdict = 'not_enough_data' then null else g.verdict end,
 kill_rule_hit = g.kill_rule_hit, grade_note = g.note, graded_at = case when g.verdict = 'not_enough_data' then null else now() end,
 check_date = coalesce(g.new_check_date::date, p.check_date), actual = coalesce(g.actual::text, p.actual),
 status = case when g.verdict = 'not_enough_data' then p.status else 'checked' end
from json_to_recordset($1::json) as g(proposal_id uuid, verdict text, kill_rule_hit boolean, note text, new_check_date text, actual json)
where p.id = g.proposal_id;

